    summary: "《永乐大典》是明成祖朱棣敕令纂修的官修类书，由解缙、姚广孝等两千余位学士历时五年修成，永乐五年（1407）定稿、永乐六年（1408）写成清本。全书凡二万二千八百七十七卷，目录六十卷，分装一万一千零九十五册，收书达七八千种，总字数约三亿七千万，被称誉为「世界有史以来最大的百科全书」。其书以《洪武正韵》为纲，用韵以统字、用字以系事，整段收录原书而不删改，保存了宋元以前大量佚籍。正本毁佚、副本历经劫难，今存约八百余卷，为辑佚古籍之渊海。",
    background: "建文四年（1402）六月，燕王朱棣以「靖难」夺取政权，入南京即位，改元永乐。新朝根基未稳，方孝孺被诛十族，士林疑惧，人心未附。朱棣欲在文治上比肩甚至超越历代汉唐盛世，并消除前朝士大夫的抵触情绪，遂以修书为羁縻笼络之术，将大批江南文士纳入馆阁。永乐元年（1403）七月，帝召翰林院学士谕以修纂之事，旨在搜罗天下古今群书，纂修旷世巨帙。太祖朱元璋在位时曾有修类书之志而未就，成祖此命亦含承继父志之意。其修书宗旨见诸谕旨：「凡书契以来经史子集百家之书，至于天文、地志、阴阳、医卜、僧道、技艺之言，备辑为一书，毋厌浩繁。」此举既是文治盛饰，又可消弭士林与新朝之隔阂，更欲彰显天下一统的宏大国家气象。",
