          "初修之局规模尚隘，执事者一百四十七人，多为翰林院、国子监官生。解缙才思敏捷而性近疏阔，意欲速成，于去取之间未加详考。永乐二年（1404）十一月，初稿进呈，赐名《文献大成》。帝览之，以其搜采未广、编次未精，谕曰「尚多未备」，遂命重修。盖《文献大成》仅就文渊阁现存秘籍排比，未能网罗天下载籍，与帝「备辑为一书」之初衷相去甚远；且解缙时以立储之议忤旨，帝渐疏之，修书之局须另简重臣主持，方能厌服众望。",
          "永乐三年（1405）正月，再修之局开焉。帝命太子少师姚广孝、礼部侍郎刘季篪与解缙同监修，而以布衣陈济为都总裁。广孝虽释门中人，实为靖难首功，帝借其威望以弹压群士；陈济博学强记，为帝所知，特起于草野。一时征调修纂者，有翰林院修撰、编修、检讨、庶吉士，六部主事、中书舍人，国子监监生，以及四方荐举之宿儒；又有善书官生专司缮写。合纂修、誊录、圈点、教授、校对诸色人等，共两千一百六十九人，可谓旷代之局，极一时之选。"
