          "《永乐大典》之形制，为包背装，黄绢书衣，硬壳裱以黄绫，庄重异常。书册高五十余厘米、宽三十余厘米，开本宏阔，置于架上如城砖然。每页朱丝栏，手绘金色边框，板框内天地分明。正文为大字楷书，端正遒劲；所引原书文字则为小字，双行附注于事目之下。卷首有御制序文及凡例、目录。全书以韵为序，自《洪武正韵》平声「东」字起，依次排列，终于韵目之末。检阅之法，先审字音，再按韵检索，即可得相关事目与原文，取用之便，前代类书未之有也。",
          "其「整段收录、不删改一字」之原则，初出之于省事，而终收存佚之功。历代类书如《艺文类聚》《太平御览》，多为摘句割裂，原书面目因之破碎；大典则将原书整段移录，甚至全书收入。后世散佚之籍，如《旧五代史》《续资治通鉴长编》等，其全帙或残篇赖大典得存真于抄本之中。所收书目，经部六千余种、史部一千二百余种、子部一千余种、集部三千余种，天文、地志、阴阳、医卜、僧道、技艺之书亦各以类从，宋元以前佚书赖此存者不可胜数。",
