    summary: "《本草纲目》为明代医药学家李时珍历时二十七载编纂的中国古代药学集大成之作，万历六年（1578）脱稿。全书五十二卷，约一百九十万字，载药一千八百九十二种，较前代新增三百七十四种，附方一万一千零九十六首，插图一千一百余幅。书中按水、火、土、金石、草、谷、菜、果、木、服器、虫、鳞、介、禽、兽、人十六部、六十类编排，创立了科学的药物分类体系。万历二十四年（1596）由金陵胡承龙首刊后，历代刊刻不辍，并先后被节译或全译为拉丁文、法文、俄文、英文、德文、日文、韩文等文字，译传数十国，在世界科技史上占有重要地位。",
    background: "明代中叶以后，社会经济空前繁荣，白银大量内流，市镇蓬勃兴起，海外贸易与内陆水陆交通畅通无阻。隆庆元年（1567）开放福建月港，沿海商船通达东西两洋，南洋各地物产源源涌入中国，乳香、没药、苏合香、檀香、番木鳖等外来香药、南洋药物大量输入，旧有本草已不能尽收天下物产。而自宋人唐慎微《经史证类备急本草》成书以来数百年，本草学再无全面整理，历代传抄中舛错层出，或一物而析为二三，或二物而混为一品；且明代自宪宗、世宗以来帝王崇道，方士得幸，嘉靖帝朱厚熜尤嗜斋醮炼丹，社会上附会道家炼丹、服食金石之毒药者众，轻则伤身，重则殒命。李时珍出身蕲州世医，长年行医于民间，在实地行医考察中深感旧方误人不浅，目睹病家因药误而枉死者不在少数，遂立志以一人之力重新搜罗天下物产，考辨名物，正本清源，重修一部翔实可靠的本草。",
