    interpretation: "《本草纲目》的价值远超一部药书。李时珍以「医者贵在格物」的实证精神，把药物分类从传统的上、中、下三品改为按自然属性归类，分十六部、六十类，同类相聚，相邻为伍，已具近世自然分类之雏形，较瑞典林奈《自然系统》（1735年）早一个半世纪以上。书中订正历代本草舛误数百处，逐一辨析药物名称、产地、形态、炮制与主治，并注明出处，对道家金石丹药之妄说多有驳正，体现了明代中后期求实辨伪的学术风气。其影响亦不限于中国：十七世纪东传日本、朝鲜，十八、十九世纪西渐欧洲，达尔文《动物和植物在家养下的变异》曾称引其关于鸡、金鱼变异的记载，视为「中国古代的百科全书」。李时珍以布衣之身，历二十七年，成此巨帙，书成即欲上之朝廷而未及见其刊行，其孤诣苦心，终使中国古代本草学集其大成，并为世界科学史所公认。",
