      {
        heading: "劫后传薪光被四海",
        paragraphs: [
          "明清易代之后，《天工开物》的命运一波三折。乾隆年间编纂《四库全书》，此书因书中有触犯时忌的字样，未获收入，纪昀等四库馆臣于《四库全书总目》中亦未著录。加之民间藏本日稀，乾嘉学者虽偶有称引，多不得见全帙；道咸以降，此书在国内几近失传，宋应星其人其书，遂湮没无闻近三百年。一部总结中华百工技艺的巨著，在它的故土反而失去了踪迹，这本身就是文化史上令人扼腕的一页。",
          "与国内的冷落相反，《天工开物》在东邻日本获得了新生。十七世纪末，此书经海商传入日本，江户时代学者竞相购读、传抄、翻刻。享保年间（1716—1736）以后，它成为本草学与产业技术的重要参考，明和八年（1771）菅生堂刻本风行一时。伊藤东涯、平贺源内、佐藤信渊等学者都从中汲取知识，用以考订名物、改进工艺，推动了江户时代的「开物之学」。日本所存的崇祯刻本与和刻本，后来成为中国回传此书的重要桥梁——典籍的命脉，竟要借异邦的收藏才得以延续。",
          "十九世纪以降，《天工开物》渐次传入欧洲，法文、英文节译本相继问世。达尔文在《动物和植物在驯养下的变异》中引用书中关于家蚕变异的记载，称其为「权威著作」；英国学者李约瑟在《中国科学技术史》中大量援引此书，誉之为「中国17世纪的工艺百科全书」。民国十一年（1922），地质学家丁文江在云南图书馆发现崇祯十年刻本，撰文表彰；民国十七年（1928），陶湘据以影印，收入《喜咏轩丛书》。这部湮没近三百年的科技巨著，终于在国内重见全帙，宋应星也因此被后世追尊为中国古代科技史的巨擘。"
        ]
      }
