        heading: "万里遐征·九死一生",
        paragraphs: [
          "崇祯九年（1636）九月十九日，霞客年五十，自江阴放舟，作生平最长的一次「万里遐征」。同行者有江阴迎福寺僧静闻，及一仆顾行，志在西南边徼，补舆地之阙。经浙江杭州、金华，入江西，游龙虎山、武功山；崇祯十年（1637）正月入湖南，历衡山、九疑山，下永州、郴州。所记《浙游日记》《江右游日记》《楚游日记》等，逐日不辍。此行一改往昔「有方之游」之例，不计程期，不避蛮烟瘴雨，惟以穷源溯流为务。静闻发愿将所刺血书《法华经》送供云南鸡足山，二人遂结伴西行。",
          "崇祯十年（1637）二月十一日夜，泊舟湘江新塘，突遇群盗执炬登舟，刀伤舟人，衣物钱帛被劫一空。霞客身免于难，静闻受创，仆顾行亦被伤。舟人劝其折返，霞客慨然不允，质衣市舟，继续南行。不意祸不单行，静闻伤重，辗转衡阳、南宁，崇祯十一年（1638）三月病逝于南宁崇善寺，遗嘱望葬鸡足山。霞客遂负其骨灰，间关数千里，誓达鸡足，以践生死之约。其《粤西游日记》于南宁崇善寺诸条，字字悲恻，读者犹能想见其孤身南行之苦。",
          "崇祯十一年（1638）三月入广西，历桂林、阳朔、柳州、南宁，探寻七星岩、象鼻山诸洞；九月入贵州，经独山、都匀、贵阳；十月入云南，经曲靖、昆明、晋宁。在滇东、滇南考察石林、溶洞、瀑布、温泉一百数十日；崇祯十二年（1639）正月抵丽江，受丽江土司、知府木增礼遇，留住解脱林，应木增之请纂修《鸡足山志》，并为木增诗稿作跋。在腾越州（今腾冲），考察火山遗迹与硫磺塘地热，记打鹰山「山顶之石，色赭赤而质轻」，为我国最早的火山地质记录之一。此行对云贵石灰岩高原岩溶地貌的系统考察，比欧洲学者同类工作早百余年。"
        ]
