    interpretation: "《徐霞客游记》的价值，远在卧游山水之上。霞客之前，我国地理之学重在书斋考据，《禹贡》「岷山导江」之说相沿千余年，无人亲至江源一证。霞客溯金沙江而上，著《江源考》《盘江考》，断言「推江源者，必当以金沙为首」，使长江正源之说为之一变；于腾越打鹰山记火山石与硫磺塘地热，是我国最早的火山地热观察记录；其于云贵、两广三百余处岩洞之实测，更构成对石灰岩岩溶地貌的系统描述，比欧洲同类考察早百余年。书中逐日记程，兼载物产、物价、民俗、土司制度，遂成晚明社会一份活的实录。以一书而兼科学与文学两长，与李时珍《本草纲目》、宋应星《天工开物》、徐光启《农政全书》并列为有明一代科学巨著。它标志着中国地理学自文献辑录转向实地踏勘，被誉为中国古代地理学奠基巨制，诚非过誉。",
