    interpretation: "内阁制度二百余年的演化，即一部「无相之相」的中枢变迁史。太祖废相，本意在于根绝臣下专权，使权柄永归天子一人；然而以一人之身理天下万机，制度上既不可行，太祖之后诸帝又无其勤勉，近臣辅政遂势所必至。内阁初设时品秩仅五品、六品，无属官、无印信，完全依附皇权；票拟成为定例之后，阁臣手中有了近似相权的工具，却没有丞相统率百官的法定地位。正因名实不符，首辅欲任事，须借皇权之威（如张居正结冯保、行考成法），或迎帝意以固位（如嘉靖朝张璁以下）；皇帝欲专断，则借司礼监批红与厂卫制衡阁权。故明代阁权之消长，不在制度而在人事：遇贤相则治，遇权阉则乱。终明一代，内阁始终未能成为稳定的中枢——崇祯朝十七年命相五十人，即是这一制度无法自我修复的明证。清代设内阁而实权归于军机处，可视为对这一困局的历史回应。",
