    interpretation: "八股取士之深层逻辑，在于将「选官」与「教化」合为一事。明初承元末大乱之后，朱元璋既需迅即建立官僚队伍，更需将天下士人纳入王朝秩序：以《四书》《五经》命题，是定其学之所宗；以程朱注疏为标准答案，是定其说之所归；以八股格式为程式，是定其文之体。三者叠加，则士子之读书、思考、行文，自始至终皆在朝廷预设之轨道内。较之唐宋取士重诗赋、尚可各抒才情，八股既须「代古人语气」行文，又禁绝个人议论，其为牢笼之术，实更深密。就实效而言，此制确曾成功：学校、科举、选官合为一体，为王朝输送了大批官僚，公卿大夫十九出于科第，政权向寒门开放，社会流动有序。然其代价同样深重：士人思想日趋僵化，学风空疏，不习实用；逮至近代，国势阽危，始知八股之士不足应天下之变。八股兴衰四百余年，正见出一项制度若只求整齐划一、便于驭下，终将与培植真才之初衷背道而驰。",
