    background: "明初定都金陵，漕运之费省，北方军饷多由江浙海运供给，岁额有限。靖难之役后，成祖朱棣决意迁都，自永乐四年（1406）起调集天下匠役营建北京，永乐十九年（1421）正式以北京为京师。自此京师百官俸粮、京军月粮并北边馈饷，悉仰给于东南，岁运之数动以百万计。然元末以来会通河淤废，运道中断，漕粮唯有取道海路，风涛险恶，漂没甚巨；运河一日不通，京师一日不安。永乐九年（1411），成祖命工部尚书宋礼重浚会通河，采纳汶上老人白英之策，筑戴村坝遏汶水入运，南旺分水枢纽遂成；永乐十三年，平江伯陈瑄又督凿清江浦，引淮河通漕。至此京杭运河全线畅达，明廷遂罢海运而专行河运，漕运制度由此奠基。",
