          "宣德六年（1431），平江伯陈瑄奏行兑运法。其时民运苦远，军运苦费，陈瑄乃令江南民户不再亲运远仓，就近将正粮交与官军，另加耗米以代偿军运之费。耗米初定正粮一石加耗一斗，其后递增至四五斗，复有脚价、芦席、竹木之征。兑运法行，民户但输粮于本地水次，军船直达京、通二仓，省费便民，支运渐废。陈瑄以勋臣久镇淮安，熟谙漕弊，故有此请，宣宗从之，至正统、景泰间，兑运已居十之七八。",
