    interpretation: "都察院与六科之设，是朱元璋废除丞相、独揽皇权后精心设计的配套工程。丞相既去，天子直统百司，监察之权遂一分为二，分而不专：都察院纠劾百司、巡按地方，六科封驳诏敕、稽察六部，互不统属，彼此纠弹。以七品之官临二品之臣，以小制大、以卑临尊，官卑则禄薄无求、勇于任事，权重则震慑百僚、无敢玩愒；而科道互纠，使监察权自身亦受牵制，无从坐大。其妙处在于皇权居上裁断，操纵自如。然其隐患亦系于此：制度运转全恃皇帝一人之勤明——皇帝怠惰，则章奏留中、封驳无凭；皇帝昏聩，则科道为权臣宦官所用。张居正以考成法驾驭科道，监察成为行政之鞭策，一时极效；及其既死，人亡政息，门户纷争，言路壅塞，监察反成政务壅塞之由。明初以肃清吏治立国，明末以党争亡国，同一制度，其兴其亡，皆因皇权，此其终与明俱亡之故也。",
