    interpretation: "明代宗藩制度，是一部以血缘加固皇权、终被血缘所累的完整标本。朱元璋以汉晋封建太重、元室宗亲无权为鉴，设计塞王守边之制，又以胡蓝之狱诛尽功臣，把军权集中到皇子手中。短期看他成功了：皇权稳固，功臣无能为患。但他未悟汉晋之失不在分封本身，而在诸王拥兵。靖难之役证明，屏藩一旦兵强，首先威胁的恰是皇位。朱棣得位后反手削藩，彻底缴了宗室的械，代价是把宗室变成不农不仕、坐食岁禄的寄生阶层。分封不锡土、列爵不临民、食禄不治事，消弭了汉晋之乱，却制造了新的死结：皇权要安全，宗室就不能有权；宗室无权，就只能以天下供养。天下供养一家，一家人口指数膨胀，宗禄倍于京储，财政必然崩溃。终明一世，调整只在禄米条例上修补，未敢动制度根本。其亡也，宗室与国同尽。家天下与集权，至此成一个解不开的死结。",
