    interpretation: "《农政全书》之可贵，不在辞章之美，而在其书生于危世，事事落到实处。徐光启以「欲求超胜，必先会通」之胸襟，治西学而不盲从，述古法而不泥旧，把西洋水利器械与数千年耕作经验熔于一炉，开中西科技会通之先路。其书以农本为经、荒政为纬，所重不止于丰产，更在于备荒——旱潦无常之年，甘薯、木棉之属皆活命之物，此即「既能丰产、又可备荒」之深意。后世论明代科技，以此书与《本草纲目》《天工开物》并称；论中西文化交流，则《泰西水法》之入农书，尤为实证。它证明传统农学不必故步自封，可以吸收外来知识而自成新统；而徐光启以大学士之身、临终之岁，成此七十万言之书，可见其忧国之深、谋国之远，非寻常书生所能及。",
