    interpretation: "《三国演义》之关键，在于以小说重写历史。章学诚「七分实事，三分虚构」一语，道破其写作范式：史实为骨，虚构为肉，凡虚构必依附于史事关节，使读者不觉其假。此种写法，上承《左传》《史记》之叙事传统，下开历史演义一脉，影响中国人数百年之三国认知。其正统观以蜀汉继汉，本于朱熹之绪，又与民间情感相合，遂成尊刘抑曹之定局。然小说之失亦在过求忠义智勇之极致：鲁迅《中国小说史略》评其「欲显刘备之长厚而似伪，状诸葛之多智而近妖」，最中肯綮。要之，此书既是一部历史小说，亦是一部民族心史：乱世之痛、忠义之慕、正统之执，皆寄寓其中，其影响不仅在文学史，更在中国人之精神世界。",
