          "施耐庵生平，正史无传，明人记载多出传闻。郎瑛《七修类稿》称「钱塘施耐庵的本」，胡应麟《少室山房笔丛》谓之「元人施某」，嘉靖十九年（1540）高儒《百川书志》著录「《忠义水浒传》一百卷，钱塘施耐庵的本，罗贯中编次」。罗贯中为元末明初小说家，太原人，一说钱塘人，撰《三国演义》行于世。施耐庵或为书会才人，或传曾入张士诚幕，皆无确据，要之以元末明初为近是。《水浒传》实非一人一时之作，施、罗二氏荟萃宋元说话、杂剧与旧本，排比润色，遂成巨帙，成书约在元末至洪武初年。",
