        paragraphs: [
          "玄奘之后，取经之事渐离纪实，生出灵异。晚唐段成式《酉阳杂俎》已载玄奘取经途中的异闻；五代、宋初，寺院俗讲与壁画渐绘取经队伍。南宋刊《大唐三藏取经诗话》今存残本十七节，猴行者形象首次出现：一白衣秀士，自云「花果山紫云洞八万四千铜头铁额猕猴王」，一路护持三藏，降深沙神、过鬼子母国、入女人国。深沙神即沙悟净之雏形，而猪形人物尚未见。泉州开元寺南宋石塔上，刻有头戴金箍、持棒随行的猴行者浮雕，可见其形象已播于市井。",
          "入元，取经故事大备。元代《西游记平话》虽佚，仍可窥其梗概：《永乐大典》卷一万三千一百三十九引「梦斩泾河龙」一段，文字与今见百回本中相应关目相近；朝鲜汉语教科书《朴通事谚解》引述平话车迟国斗法事，注中提及孙行者除妖之语。可见元末平话已具大闹天宫、车迟国、火焰山等主要关目，且分回叙事，体制粗具长篇规模。元末明初，杨讷（字景贤）撰《西游记杂剧》六本二十四折，孙悟空之名始定，猪八戒以黑风洞妖精面貌登场，取经五众的骨架至此大致齐备。",
          "故事在市井层叠，亦在民间扎根。唐僧出身「满月抛江」的江流儿故事，融入泗州大圣信仰与目连救母的故辙，使取经多了伦理负担与俗世牵挂。民间信仰亦参与塑造：观音、二郎神、哪吒、城隍土地纷纷入列，天庭地府、龙宫魔界各具秩序，妖魔亦有洞府、喽啰、法宝与亲眷。取经故事由一位僧人的孤旅，扩展为一个神魔纷繁、秩序井然又处处映照人间的宇宙。至明中叶，主要人物、关目与结构已由数百年说唱、戏曲、刊本铺衍定型，只待大手笔将其熔铸为一部浑然长篇。"
        ]
