    interpretation: "《西游记》是一部典型的层累成书之作。从贞观年间一位僧人的十七年孤旅，到《大唐西域记》的朴质纪实，到南宋《取经诗话》中的猴行者，到元代平话、杂剧，再到明中叶百回本，前后历时九百余年，每一次改写都增添了新的趣味与寄托。作者问题至今未有定论：世德堂本不题撰人，明天启《淮安府志·艺文志》载吴承恩所著有《西游记》，清代吴玉搢、阮葵生等进而坐实，鲁迅、胡适等从之，章培恒等则提出质疑，主流仍定为吴承恩。其思想内涵儒释道三家杂糅：一面是「修心炼性」的隐喻，心猿意马，降魔即降心；一面是对嘉靖朝政的影射，车迟国、比丘国之设，皆有现实指向。它以游戏笔墨写神魔世界，却处处映照人间秩序，这正是其历久弥新的根由。",
