    interpretation: "开中法的深层逻辑，是以国家垄断的盐利购买民间粮食，再把粮食送到边防前线。朝廷不必亲自转运，商人趋利自往；边仓、盐场、行盐地构成一条完整的信用链条，盐引即是有价证券。商屯的出现，说明这一制度还能自发引导资本与劳动力流向边疆，寓军屯于商运，堪称巧妙。其失败亦源于同一逻辑：叶淇变法把实物财政改为货币财政，效率提高而风险转移——边饷从此仰赖太仓银两拨发，中间多出朝廷一层调度，一旦军费膨胀或拨付不及时，边储立见虚耗。盐引又为权贵占窝、转卖所侵蚀，信用链条断裂，积引壅滞，终至纲法垄断。由开中而折色、由折色而纲盐、由纲盐而票盐，明清盐业结构的每一次变动，都是财政需求与市场力量博弈的结果。",
