    interpretation: "鱼鳞图册之制，核心在「以田为经、以人为纬」的双册结构：黄册管人，鱼鳞册管田，两册互核，使田、户、赋三者钩连。其深层逻辑是国家权力越过中间豪强，直接掌握每一块田土的坐落、四至、土色与科则，把田赋征收建立在地籍而非户等之上，这在古代赋役制度史上是一大转折。洪武二十六年八百五十万顷之数，数字本身固有争议，但反映的是明代国家大规模清丈的能力与决心。万历清丈与一条鞭法相辅相成，赋役合于田亩，为清代摊丁入亩铺平道路。鱼鳞图册之存废修废，实为王朝治理能力的晴雨表：册籍修则赋役均，册籍坏则兼并兴，此非一纸簿书之得失，乃国家根基之动摇。",
